  z-index: 200;
}
.modal-panel {
  background: #fff;
  border-radius: 1rem;
  box-shadow: 0 20px 60px rgba(0,0,0,0.2);
  width: 520px;
  max-width: 90vw;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  border-bottom: 1px solid #e2e8f0;
}
.modal-header h3 {
  margin: 0;
  font-size: 1rem;
  color: #334155;
}
.close-btn {
  background: #f1f5f9;
  border: none;
  width: 32px;
  height: 32px;
  border-radius: 0.5rem;
  font-size: 1rem;
  color: #64748b;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.close-btn:hover { background: #e2e8f0; }
.experiments-grid {
  padding: 1.25rem;
  overflow-y: auto;
}
.exp-card {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0.75rem;
  padding: 1rem;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}
.exp-card:hover {
  border-color: #10b981;
  box-shadow: 0 4px 16px rgba(16,185,129,0.12);
  transform: translateY(-2px);
}
.exp-icon { font-size: 2rem; line-height: 1; }
.exp-name { font-size: 0.85rem; font-weight: 700; color: #1e293b; }
.exp-desc { font-size: 0.72rem; color: #64748b; line-height: 1.5; }
.exp-steps-count {
  font-size: 0.65rem;
